<script setup lang="ts">
import{onBeforeUnmount,onMounted,ref}from"vue";import{ElMessage}from"element-plus";import{MagicStick,Refresh}from"@element-plus/icons-vue";import{api}from"@/api";import{consumeSse}from"@/utils/sse";import{useUserStore}from"@/stores/user";import{err,fmt}from"@/utils/format";import type{GrowthResponse,GrowthResult}from"@/types/api";import PageHeader from"@/components/common/PageHeader.vue";import StateView from"@/components/common/StateView.vue";import SectionPanel from"@/components/common/SectionPanel.vue";
const user=useUserStore(),target=ref(''),result=ref<GrowthResponse|null>(null),loading=ref(true),running=ref(false),error=ref(''),stream=ref('');let controller:AbortController|undefined;async function load(){loading.value=true;try{const h=await api.growths(user.userId!);if(h[0]){result.value=await api.growthDetail(h[0].id);target.value=result.value.target_job}}catch(e){error.value=err(e)}finally{loading.value=false}}async function run(){if(!target.value.trim()){ElMessage.warning('请填写目标岗位');return}running.value=true;controller=new AbortController();try{await consumeSse<GrowthResult>('/stream/growth',{user_id:user.userId,target_job:target.value},{chunk:x=>stream.value+=x,error:m=>{throw new Error(m)}},controller.signal);result.value=await api.growth({user_id:user.userId,target_job:target.value});ElMessage.success('成长规划生成完成')}catch(e){if((e as Error).name!=='AbortError')ElMessage.error(err(e))}finally{running.value=false}}onMounted(load);onBeforeUnmount(()=>controller?.abort());
</script><template><div><PageHeader title="个人就业成长规划" description="根据就业画像与目标岗位，生成阶段化的能力提升路线。"><el-input v-model="target" placeholder="目标岗位（必填）" class="target-input"/><el-button type="primary" :icon="result?Refresh:MagicStick" :loading="running" @click="run">{{result?'重新生成':'生成规划'}}</el-button></PageHeader><div v-if="running" class="stream-panel"><el-icon class="is-loading"><Refresh/></el-icon><b>AI正在制定成长路径</b><pre>{{stream.slice(-1200)||'正在读取档案与知识资源...'}}</pre></div><StateView :loading="loading" :error="error" :empty="!result" empty-text="暂无成长规划" @retry="load"><template #content><div class="growth-head"><div><span>目标岗位</span><h2>{{result?.target_job}}</h2><p>{{result?.result.current_situation}}</p></div><div><span>预计达标时间</span><strong>{{result?.result.expected_timeline}}</strong><small>{{fmt(result?.created_at)}}</small></div></div><div class="growth-layout"><SectionPanel title="阶段学习路线"><el-timeline><el-timeline-item v-for="(s,i) in result?.result.learning_roadmap" :key="s.stage" :timestamp="`阶段 ${i+1}`" placement="top"><div class="timeline-card"><h4>{{s.stage}}</h4><p>{{s.focus}}</p><ul><li v-for="x in s.tasks" :key="x">{{x}}</li></ul><div class="milestone">里程碑：{{s.milestone}}</div></div></el-timeline-item></el-timeline></SectionPanel><div><SectionPanel title="能力缺口"><div v-for="g in result?.result.ability_gaps" :key="g.skill" class="gap-item"><div><b>{{g.skill}}</b><el-tag size="small" :type="g.importance==='必须'?'danger':'warning'">{{g.importance}}</el-tag></div><p>{{g.description}}</p><span>学习难度：{{g.difficulty}}</span></div></SectionPanel><SectionPanel title="推荐学习资源"><ul class="result-list"><li v-for="x in result?.result.recommended_resources" :key="x">{{x}}</li></ul></SectionPanel></div></div></template></StateView></div></template>
